/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ImportLookupView, ReviewLookupView, ImportLookupResponse, ImportSummaryState, ImportAppendTracklist
 *   Constants: reviewValuePathSchema, lookupViewSchema, reviewLookupViewSchema, lookupResponseSchema
 * Internal
 *   Functions: comparisonFor, candidateSchemaFor, lookupViewFor
 *   Constants: integer, run, text, candidateKey, releaseId, mbid, source, groupKey, trackPath, valuePath,
 *              reviewTrackPath, slotId, bases, basis, reviewBasis, flagReasons, discNumber, trackNumber,
 *              comparisonSchema, pairSchema, subsetSchema, reviewComparisonSchema, proposalSchema, groupSchema,
 *              lookupValueSchema, expectedRows, reviewLookupValueSchema, appliedSchema, reviewAppliedSchema,
 *              rowTitle, knownDuration, appendTracklistSchema, summarySchema
 * @end-catalog */

import { z } from 'zod';
import { artistEntrySchema, expectedTracklistRowSchema, importDateSchema, labelEntrySchema, uuidSchema } from './adminNamingSchema';

/**
 * The strict schema of an import's metadata lookup view (GET /api/admin/v1/imports/:id/lookup), mirroring the server's allowlist
 * (src/administration/lookup/lookupView.ts): bounded candidate evidence, groups, the preselection, the applied values with their
 * conflicts and flags, and what Publish waits for; and the import's summary state (src/administration/import/adminImportSummary.ts).
 * An existing-Album review's view (GET /catalog-reviews/:id/lookup) shares it and also admits the catalog trigger, the exact-count
 * basis, the subset differences and comparison, the review-only value paths, flag reasons and conflict precision, and the applied
 * pairing; an import's view refuses every one of them. The summary reads (importSummaryQuery.ts, catalogReviewSummaryQuery.ts) load
 * it with the read, so no chunk that shares those queries carries it.
 */
const integer = z.number().int().nonnegative();
const run = z.number().int().min(1);
const text = z.string().max(1000);
/** A MusicBrainz release's key, or an iTunes-only candidate's (`itunes:<collection ID>`); the release ID is the MBID or the collection ID. */
const candidateKey = z.string().regex(/^(?:musicbrainz:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|itunes:[1-9]\d{0,11})$/);
const releaseId = z.string().regex(/^(?:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|[1-9]\d{0,11})$/);
const mbid = z.string().regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
const source = z.enum(['musicbrainz', 'itunes']).default('musicbrainz');
const groupKey = z.string().regex(/^[a-f0-9]{64}$/);
const trackPath = /^tracks\.([^.]+)\.(?:title|discNumber|trackNumber)$/;
/** A lookup value path: four Album values, or a file's title, Disc or Track Number. */
const valuePath = z.string().max(80).refine(path => /^album\.(?:title|artists|label|releaseDate)$/.test(path)
  || uuidSchema.safeParse(trackPath.exec(path)?.[1]).success, 'Invalid lookup path');
const reviewTrackPath = /^tracks\.([^.]+)\.(?:title|discNumber|trackNumber|artists)$/;
/** A review's lookup value path: also the Album's expected tracklist and each member's track Artist entries. */
export const reviewValuePathSchema = z.string().max(80).refine(path => /^album\.(?:title|artists|label|releaseDate|expectedTracklist)$/.test(path)
  || uuidSchema.safeParse(reviewTrackPath.exec(path)?.[1]).success, 'Invalid lookup path');
const slotId = uuidSchema.nullable();
const bases = ['releaseId', 'barcode', 'catalogNumber', 'onlyMatchingGroup'] as const;
const basis = z.enum(bases);
/** A review also preselects the only matching group whose release has as many tracks as the Album has members. */
const reviewBasis = z.enum([...bases, 'exactTrackCount']);
const flagReasons = ['characters', 'length', 'format', 'size', 'placeholder'] as const;
const discNumber = z.number().int().min(1).max(999);
const trackNumber = z.number().int().min(1).max(9999);

/** A ranked candidate's counts and differences: an import's three kinds, or a review's six. */
const comparisonFor = <Difference extends z.ZodType>(difference: Difference, kinds: number) => ({
  trackCount: z.object({ local: integer, candidate: integer }).strict(), discCount: z.object({ local: integer.nullable(), candidate: integer }).strict(),
  differences: z.array(difference).max(kinds), unknownLocalDurations: integer, unknownCandidateDurations: integer
});
const comparisonSchema = z.object(comparisonFor(z.enum(['trackCount', 'discCount', 'duration']), 3)).strict();
/** A review member paired with a release track at its Disc and Track Number. */
const pairSchema = z.object({ slotId: uuidSchema, discNumber, trackNumber }).strict();
/**
 * A review candidate's subset comparison: tracks left out as video, data or pregap, the pairing and its pairs, the missing-file rows
 * the release would add, and the members no audio track can pair with.
 */
const subsetSchema = z.object({ leftOutTracks: integer, pairing: z.enum(['unique', 'ambiguous', 'none']).nullable(), pairs: z.array(pairSchema).max(100),
  missingTrackCount: integer.nullable(), unpairableSlotIds: z.array(uuidSchema).max(100) }).strict();
const reviewComparisonSchema = z.object({ ...comparisonFor(z.enum(['trackCount', 'discCount', 'duration', 'pairing', 'tooManyTracks', 'tracklistInvalid']), 6),
  subset: subsetSchema.nullable() }).strict();
/** One candidate's evidence with its mode's comparison (zod refuses to extend a refined object, so each mode builds its own). */
const candidateSchemaFor = <Comparison extends z.ZodType>(comparison: Comparison) => z.object({
  // An iTunes-only candidate, and whether it was not checked against MusicBrainz (MusicBrainz's, unchecked, from a server sending none).
  key: candidateKey, releaseId, source, notChecked: z.boolean().default(false), status: z.enum(['matching', 'unverified', 'notMatching', 'incomplete']), title: text.nullable(), artist: text.nullable(),
  label: text.nullable(), catalogNumber: text.nullable(), barcode: z.string().max(14).nullable(), country: z.string().max(2).nullable(), date: importDateSchema.nullable(),
  formats: z.array(z.string().max(100)).max(20), trackCount: integer.nullable(), comparison: comparison.nullable(), groupKey: groupKey.nullable(), artistMismatch: z.boolean().nullable(),
  // Whether a protected front-artwork preview exists (never an address); false from a server that sends none.
  artwork: z.boolean().default(false)
}).strict().refine(candidate => candidate.key === `${candidate.source}:${candidate.releaseId}`, 'Mismatched lookup candidate');
/**
 * The values a matching group would write, with the MusicBrainz ID each entry and the label credit (null from a server that sends
 * none); text is evidence and is shown, never applied from here.
 */
const proposalSchema = z.object({
  albumTitle: text, artists: z.array(z.object({ name: text, role: z.enum(['primary', 'featured']), joinPhrase: z.string().max(200).nullable(), musicBrainzId: mbid.nullable().default(null) }).strict()).max(50),
  label: text.nullable(), labelMusicBrainzId: mbid.nullable().default(null), releaseDate: importDateSchema.nullable(), tracks: z.array(z.object({ discNumber: integer, trackNumber: integer, title: text }).strict()).max(100)
}).strict();
const groupSchema = z.object({ groupKey, representativeKey: candidateKey, memberKeys: z.array(candidateKey).max(25), proposal: proposalSchema }).strict();
/** A conflict's lookup value in its draft form: a title, a Disc or Track Number, a date, a label or the Artist entries. */
const lookupValueSchema = z.union([z.string().max(300), z.number().int().min(1).max(9999), importDateSchema, labelEntrySchema, z.array(artistEntrySchema).max(20)]);
const expectedRows = z.array(expectedTracklistRowSchema).min(1).max(100);
/** A review conflict's lookup value: also the expected tracklist's rows, which only `album.expectedTracklist` holds. */
const reviewLookupValueSchema = z.union([...lookupValueSchema.options, expectedRows]);
/** The applied values, conflicts and flags of an import (at most 305 each, one per value path). */
const appliedSchema = z.object({
  run, candidateKey: candidateKey.nullable(), releaseId: releaseId.nullable(), choice: z.enum(['preselected', 'chosen', 'none']), basis: z.union([basis, z.literal('chosen')]).nullable(),
  // An iTunes-only application flags its values; `notChecked` when MusicBrainz could not rule it out.
  source, notChecked: z.boolean().default(false),
  values: z.array(z.object({ path: valuePath, slotId }).strict()).max(305),
  // `musicBrainzId`: the values differ only in the MusicBrainz IDs of entries or the label that agree in names, roles and phrases.
  conflicts: z.array(z.object({ path: valuePath, slotId, lookup: lookupValueSchema, answer: z.enum(['mine', 'lookup']).nullable(), musicBrainzId: z.boolean().default(false) }).strict()).max(305),
  flagged: z.array(z.object({ path: valuePath, reason: z.enum(flagReasons) }).strict()).max(305)
}).strict();
/**
 * A review's applied values, conflicts and flags (at most 406 each, the review's value paths): a conflict says whether its date only
 * adds `precision` and holds rows only on the expected tracklist; the label is flagged `notApplicable` when the review does not show
 * its first label Credit, and a member `noTrackCredit` when its release track has no usable credit; `pairs` is the single pairing
 * the applied values rest on, null without one.
 */
const reviewAppliedSchema = z.object({
  run, candidateKey: candidateKey.nullable(), releaseId: releaseId.nullable(), choice: z.enum(['preselected', 'chosen', 'none']), basis: z.union([reviewBasis, z.literal('chosen')]).nullable(),
  source, notChecked: z.boolean().default(false),
  values: z.array(z.object({ path: reviewValuePathSchema, slotId }).strict()).max(406),
  conflicts: z.array(z.object({ path: reviewValuePathSchema, slotId, lookup: reviewLookupValueSchema, answer: z.enum(['mine', 'lookup']).nullable(), musicBrainzId: z.boolean().default(false),
    precision: z.boolean() }).strict().refine(conflict => (conflict.path === 'album.expectedTracklist') === expectedRows.safeParse(conflict.lookup).success
    && (!conflict.path.endsWith('.artists') || Array.isArray(conflict.lookup)), 'Invalid lookup value')).max(406),
  flagged: z.array(z.object({ path: reviewValuePathSchema, reason: z.enum([...flagReasons, 'notApplicable', 'noTrackCredit']) }).strict()).max(406),
  pairs: z.array(pairSchema).max(100).nullable()
}).strict();
/** A lookup view of one mode: its triggers, candidates, preselection bases, applied values and the value paths it can answer. */
const lookupViewFor = <Trigger extends z.ZodType, Candidate extends z.ZodType, Basis extends z.ZodType, Applied extends z.ZodType, Path extends z.ZodType>(mode: {
  trigger: Trigger; candidate: Candidate; basis: Basis; applied: Applied; path: Path; answers: number;
}) => z.object({
  run, state: z.enum(['queued', 'running', 'retrying', 'complete', 'unavailable', 'stopped', 'superseded']),
  issue: z.enum(['permissionLost', 'grantExpired', 'notConfigured', 'sourceUnavailable', 'sourceBusy', 'fileSetChanged', 'projectClosed']).nullable(),
  outcome: z.enum(['candidates', 'noRelease', 'noQuery']).nullable(),
  input: z.object({ trigger: mode.trigger, submitted: z.object({ kind: z.enum(['album', 'song']), text }).strict().nullable() }).strict(),
  candidates: z.array(mode.candidate).max(25), groups: z.array(groupSchema).max(25),
  preselection: z.object({ candidateKey, basis: mode.basis, artistMismatch: z.boolean(), notChecked: z.boolean().default(false) }).strict().nullable(),
  disclosure: z.object({ unknownLocalDurations: integer, unknownLocalDiscNumbers: integer, partialComparison: z.boolean() }).strict().nullable(),
  applied: mode.applied.nullable(), staleFiles: z.array(uuidSchema).max(100),
  needsAnswer: z.object({ tie: z.boolean(), conflicts: z.array(mode.path).max(mode.answers) }).strict(), blocking: z.boolean(),
  // The iTunes fallback stage: not queried, running, waiting for an automatic retry, answered or unavailable.
  itunes: z.enum(['notQueried', 'running', 'retrying', 'answered', 'unavailable']).default('notQueried')
}).strict();
export const lookupViewSchema = lookupViewFor({ trigger: z.enum(['tags', 'folder', 'submitted']), candidate: candidateSchemaFor(comparisonSchema), basis, applied: appliedSchema,
  path: valuePath, answers: 305 });
/** An existing-Album review's lookup view: the catalog trigger, the review comparison, bases, applied values and value paths. */
export const reviewLookupViewSchema = lookupViewFor({ trigger: z.enum(['tags', 'folder', 'submitted', 'catalog']), candidate: candidateSchemaFor(reviewComparisonSchema),
  basis: reviewBasis, applied: reviewAppliedSchema, path: reviewValuePathSchema, answers: 406 });
const rowTitle = z.string().min(1).max(300);
const knownDuration = z.number().int().min(1).nullable();
/**
 * A saved append's target rows (at most 100, in Disc then Track Number order, `filled` when a member sits at the position), each
 * manifest file's known duration with its precision and whether it is appended, and the one-step numbering (`title` null keeps
 * the file's own).
 */
const appendTracklistSchema = z.object({
  albumId: z.string().regex(/^[a-f0-9]{24}$/), durationToleranceMs: z.number().int().min(0).max(60_000),
  rows: z.array(z.object({ discNumber, trackNumber, title: rowTitle, durationMs: knownDuration, filled: z.boolean() }).strict()).min(1).max(100),
  files: z.array(z.object({ slotId: uuidSchema, durationMs: knownDuration, durationPrecisionMs: z.union([z.literal(0), z.literal(1000)]), appended: z.boolean() }).strict()).max(100),
  numbering: z.array(z.object({ slotId: uuidSchema, discNumber, trackNumber, title: rowTitle.nullable() }).strict()).max(100)
}).strict();
/**
 * What the server decided for the summary: an append, the work Publish waits for (uploads, lookup, the lookup cover's staging and
 * analysis), a new Album credited only by a placeholder,
 * each shown Luna suggestion's tick state, the analysis budget left (project runs and calls, and calls today), whether this
 * server can run metadata lookup, how many identity rows of the saved draft no decision or preselection answers and, for a saved
 * append to an Album with an expected tracklist until its publication is complete, its rows (the server sends no key otherwise,
 * nor does a release before expected tracklists; both read as null).
 */
const summarySchema = z.object({
  // `cover`: the applied release's front artwork is being staged (false from a server that sends none).
  append: z.boolean(), waiting: z.object({ uploads: z.boolean(), lookup: z.boolean(), cover: z.boolean().default(false), analysis: z.boolean() }).strict(), placeholderOnly: z.boolean(),
  luna: z.array(z.object({ id: z.string().regex(/^[a-f0-9]{24}$/), tick: z.enum(['ticked', 'unticked', 'resolved', 'conflict']) }).strict()).max(1000),
  analysis: z.object({ runs: integer, attempts: integer, daily: integer }).strict(), lookupAvailable: z.boolean(), identityAnswers: integer.max(1000),
  appendTracklist: appendTracklistSchema.nullable().default(null)
}).strict();
/**
 * The lookup view (null before any run) with the import's revision, automatic-write counter and summary state, and the names lookup
 * found for each MusicBrainz ID the saved draft carries (a renamed entry keeps its ID only under one of them).
 */
export const lookupResponseSchema = z.object({ lookup: lookupViewSchema.nullable(), revision: integer, valueRevision: integer, summary: summarySchema,
  musicBrainzNames: z.array(z.object({ musicBrainzId: mbid, names: z.array(z.string().max(200)).max(32) }).strict()).max(21).default([]) }).strict();
export type ImportLookupView = z.infer<typeof lookupViewSchema>;
export type ReviewLookupView = z.infer<typeof reviewLookupViewSchema>;
export type ImportLookupResponse = z.infer<typeof lookupResponseSchema>;
export type ImportSummaryState = z.infer<typeof summarySchema>;
export type ImportAppendTracklist = NonNullable<ImportSummaryState['appendTracklist']>;
